style.css:
@-moz-document domain("soundcloud.com") {
/* Основной фон и текст */
  body, 
  #app, 
  .g-dark, 
  .l-container, 
  .l-main, 
  .l-content, 
  .pageMain,
  .siteHeader,
  .playControls__bg,
  .l-listen-wrapper,
  .l-about-rows {
    background-color: #000000 !important;
    background: #000000 !important;
    color: #e1e1e1 !important;
  }

  /* Шапка сайта */
  .header {
    background: #050505 !important;
    border-bottom: 1px solid #1a1a1a !important;
  }

  .header__navMenuItem > a,
  .header__mainMenu {
    color: #ffffff !important;
  }

  .header__navMenuItem > a:hover,
  .header__navMenuItem > a.selected {
    color: #a855f7 !important;
    border-bottom: 2px solid #a855f7 !important;
  }

  /* Строка поиска */
  .headerSearch__input {
    background-color: #111111 !important;
    color: #ffffff !important;
    border: 1px solid #222222 !important;
    border-radius: 4px !important;
  }

  .headerSearch__input:focus {
    border-color: #a855f7 !important;
  }

  /* Карточки треков и списки */
  .soundList__item,
  .trackItem,
  .sound__content,
  .chartTracks__item {
    background-color: #050505 !important;
    border-color: #151515 !important;
  }

  /* Названия треков и артистов */
  .soundTitle__title,
  .trackItem__title,
  .sc-link-dark {
    color: #ffffff !important;
  }

  .soundTitle__title:hover,
  .trackItem__title:hover,
  .sc-link-dark:hover {
    color: #a855f7 !important;
  }

  .soundTitle__username,
  .trackItem__username,
  .sc-link-light {
    color: #888888 !important;
  }

  /* Нижняя панель плеера */
  .playControls {
    background-color: #050505 !important;
    border-top: 1px solid #1a1a1a !important;
  }

  .playControls__inner {
    background: #050505 !important;
  }

  /* Кнопки плеера */
  .playButton,
  .sc-button-play {
    background-color: #a855f7 !important;
    background-image: none !important;
    border-color: #a855f7 !important;
    color: #ffffff !important;
  }

  .playButton:hover,
  .sc-button-play:hover {
    background-color: #9333ea !important;
    border-color: #9333ea !important;
  }

  /* Полоса прогресса */
  .playbackTimeline__progressBackground {
    background-color: #1a1a1a !important;
  }

  .playbackTimeline__passedProgress {
    background-color: #a855f7 !important;
  }

  .playbackTimeline__handle {
    background-color: #ffffff !important;
    border-color: #a855f7 !important;
  }

  /* Волна звука */
  .waveform__layer--progress {
    filter: hue-rotate(220deg) saturate(3) brightness(0.9) !important;
  }

  .waveform__layer--waveform {
    opacity: 0.3 !important;
  }

  /* Кнопки действия (Like, Repost) */
  .sc-button {
    background-color: #111111 !important;
    color: #dddddd !important;
    border: 1px solid #252525 !important;
  }

  .sc-button:hover,
  .sc-button-selected {
    color: #a855f7 !important;
    border-color: #a855f7 !important;
  }

  /* Боковая панель */
  .sidebarHeader__title,
  .sidebarModule__title {
    color: #a855f7 !important;
  }

  /* Скроллбар */
  ::-webkit-scrollbar {
    width: 8px;
    background-color: #000000;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #222222;
    border-radius: 4px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background-color: #a855f7;
  }
}
